// Makes real mutual TLS Ping calls to an in-process gRPC server, using certificates generated by make-certs.sh.
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <memory>
#include <string>

#include <grpcpp/grpcpp.h>

#include "mica/acceptor/service/v2/acceptor_to_mica_service.grpc.pb.h"
#include "mica/issuer/service/v2/issuer_to_mica_service.grpc.pb.h"
#include "mica/member/ping/v1/ping_service.grpc.pb.h"
#include "mica/sdk/mtls.h"

namespace ping = mica::member::ping::v1;

#define CHECK(condition)                                                          \
  do {                                                                            \
    if (!(condition)) {                                                           \
      std::cerr << "FAILED: " #condition " (" << __FILE__ << ":" << __LINE__ << ")\n"; \
      return 1;                                                                   \
    }                                                                             \
  } while (0)

class Pinger final : public ping::PingService::Service {
  grpc::Status Ping(grpc::ServerContext*, const ping::PingRequest*, ping::PingResponse* response) override {
    response->set_status(ping::PingResponse::STATUS_SUCCESS);
    response->set_service_type("test");
    return grpc::Status::OK;
  }
};

int main(int argc, char** argv) {
  if (argc != 2) {
    std::cerr << "usage: mica_mtls_test <certs dir>\n";
    return 2;
  }
  const std::string dir = argv[1];
  auto file = [&](const char* name) { return dir + "/" + name; };

  // The server requires and verifies a client certificate
  Pinger service;
  grpc::SslServerCredentialsOptions server_options(GRPC_SSL_REQUEST_AND_REQUIRE_CLIENT_CERTIFICATE_AND_VERIFY);
  auto server_credentials = mica::sdk::MtlsCredentials::FromFiles(file("ca.crt"), file("server.crt"), file("server.key"));
  server_options.pem_root_certs = server_credentials.certificate_authorities;
  server_options.pem_key_cert_pairs.push_back({server_credentials.key, server_credentials.certificate});
  int port = 0;
  grpc::ServerBuilder builder;
  builder.AddListeningPort("127.0.0.1:0", grpc::SslServerCredentials(server_options), &port);
  builder.RegisterService(&service);
  auto server = builder.BuildAndStart();
  CHECK(server != nullptr && port != 0);
  const std::string target = "localhost:" + std::to_string(port);

  auto call = [&](const mica::sdk::MtlsCredentials& credentials) {
    auto stub = ping::PingService::NewStub(mica::sdk::CreateMtlsChannel(target, credentials));
    grpc::ClientContext context;
    context.set_deadline(std::chrono::system_clock::now() + std::chrono::seconds(10));
    ping::PingResponse response;
    auto status = stub->Ping(&context, ping::PingRequest(), &response);
    return std::make_pair(status, response);
  };

  // A client trusting the right authority and presenting its certificate succeeds
  auto [ok, response] = call(mica::sdk::MtlsCredentials::FromFiles(file("ca.crt"), file("client.crt"), file("client.key")));
  CHECK(ok.ok());
  CHECK(response.status() == ping::PingResponse::STATUS_SUCCESS);

  // A client that does not trust the server's authority is rejected
  auto [rejected, unused] =
      call(mica::sdk::MtlsCredentials::FromFiles(file("other-ca.crt"), file("client.crt"), file("client.key")));
  CHECK(!rejected.ok());

  // The role libraries link: their generated clients exist
  CHECK(mica::issuer::service::v2::IssuerToMicaService::service_full_name() != nullptr);
  CHECK(mica::acceptor::service::v2::AcceptorToMicaService::service_full_name() != nullptr);

  server->Shutdown();
  std::cout << "OK\n";
  return 0;
}
